<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Receipt {{ $payment->id }} — {{ $school->name }}</title><style>body{font-family:Arial,sans-serif;color:#1f2937;margin:0;background:#f3f4f6}.receipt{max-width:680px;margin:32px auto;background:#fff;padding:42px;border-top:7px solid #facc15;box-shadow:0 2px 12px #0001}.head{display:flex;justify-content:space-between;border-bottom:1px solid #e5e7eb;padding-bottom:18px}.label{color:#6b7280;font-size:12px;text-transform:uppercase;letter-spacing:.08em}.amount{font-size:30px;font-weight:bold;color:#059669}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:28px 0}.value{font-size:16px;font-weight:600;margin-top:5px}.footer{border-top:1px solid #e5e7eb;padding-top:18px;color:#6b7280;font-size:13px}@media print{body{background:white}.receipt{margin:0;box-shadow:none}.no-print{display:none}}</style></head><body><main class="receipt"><div class="head"><div><div class="label">Official fee receipt</div><h1>{{ $school->name }}</h1><div>{{ $school->school_number }}</div></div><div style="text-align:right"><div class="label">Receipt number</div><strong>#{{ str_pad((string) $payment->id, 6, '0', STR_PAD_LEFT) }}</strong><div style="margin-top:22px" class="amount">UGX {{ number_format($payment->amount) }}</div></div></div><div class="grid"><div><div class="label">Received from</div><div class="value">{{ $payment->student->name }}</div><div>{{ $payment->student->admission_no }}</div></div><div><div class="label">Class</div><div class="value">{{ $payment->student->schoolClass?->name ?? '—' }}</div></div><div><div class="label">Academic term</div><div class="value">{{ $payment->term->name }}, {{ $payment->term->year }}</div></div><div><div class="label">Payment method</div><div class="value">{{ ucwords(str_replace('_', ' ', $payment->method)) }}</div></div><div><div class="label">Date received</div><div class="value">{{ $payment->paid_at->format('d M Y, h:i A') }}</div></div><div><div class="label">Recorded by</div><div class="value">{{ $payment->recordedBy?->name ?? 'System' }}</div></div></div>@if($payment->notes)<div class="label">Notes</div><p>{{ $payment->notes }}</p>@endif<div class="footer">Thank you. This receipt confirms payment received by {{ $school->name }}.</div><p class="no-print" style="margin-top:28px;text-align:center"><button onclick="window.print()">Print receipt</button></p></main></body></html>
